/**
 * Crypto vs. The Traditional Financial System (Section 2 · Lecture 4) — longform-presentation spotlight comp
 * (per-project: recycled with the project). Renders ONLY the middle window of the project's enhanced EDIT
 * (`media/deck-lecture/Crypto vs. The Traditional Financial System/... EDIT-esv2-75p-bg-10p-music-10p.mp4`); the EDIT's
 * own intro and closing footage are stitched back by skills/spotlight/stitch.py.
 * THEME = the lecture deck's stylesheet (lecture4-crypto-vs-trad.html): Syne + Inter, #0d0d0d, accent #F5A623.
 * Data: CryptoVsTradSpotlightData.ts, GENERATED by skills/spotlight/cue_scenes.py --emit-ts (never hand-edit).
 */
import React from 'react';
import { loadFont as loadSyne } from '@remotion/google-fonts/Syne';
import { loadFont as loadInter } from '@remotion/google-fonts/Inter';
import { SpotlightPresentation, SpotTheme } from './SpotlightPresentation';
import { SCENES, HEAD_UNTIL, TAIL_FROM, FPS } from './CryptoVsTradSpotlightData';

const syne = loadSyne('normal', { weights: ['700', '800'], subsets: ['latin'] });
const inter = loadInter('normal', { weights: ['400', '500', '600'], subsets: ['latin'] });

export const THEME: SpotTheme = {
  bg: '#0d0d0d', surface: '#141414', card: '#161616', border: '#222222', rule: '#1a1a1a',
  text: '#f0f0f0', muted: '#9a9a9a', veryMuted: '#555555',
  accent: '#F5A623', red: '#ff6b6b', blue: '#6b9fff',
  fontHead: `${syne.fontFamily}, sans-serif`, fontBody: `${inter.fontFamily}, sans-serif`,
};

export const CVT_FPS = FPS;
export const CVT_DUR = Math.round((TAIL_FROM - HEAD_UNTIL) * FPS);

export const CryptoVsTradSpotlight: React.FC = () => (
  <SpotlightPresentation scenes={SCENES} theme={THEME} headUntil={HEAD_UNTIL} tailFrom={TAIL_FROM} audio="middle-audio.m4a" />
);
